package com.ravecraft.mod.client.screen.widget;

import com.ravecraft.mod.RaveCraft;
import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.renderer.RenderPipelines;
import net.minecraft.network.chat.CommonComponents;
import net.minecraft.resources.Identifier;

/**
 * The speaker screen's GUI sprites (generated by {@code tools/textures/gen_textures.py} under
 * {@code textures/gui/sprites/speaker/}), its colours, and small text helpers shared by its widgets.
 */
public final class SpeakerSprites {
	public static final Identifier WINDOW = sprite("window");
	public static final Identifier INSET = sprite("inset");
	public static final Identifier FABRIC = sprite("fabric");
	public static final Identifier PROGRESS_TRACK = sprite("progress_track");
	public static final Identifier PROGRESS_FILL = sprite("progress_fill");
	public static final Identifier PROGRESS_KNOB = sprite("progress_knob");
	public static final Identifier SHUFFLE = sprite("shuffle");
	public static final Identifier SHUFFLE_ON = sprite("shuffle_on");
	public static final Identifier PREVIOUS = sprite("previous");
	public static final Identifier PLAY = sprite("play");
	public static final Identifier PAUSE = sprite("pause");
	public static final Identifier NEXT = sprite("next");
	public static final Identifier REPEAT_OFF = sprite("repeat_off");
	public static final Identifier REPEAT_ALL = sprite("repeat_all");
	public static final Identifier REPEAT_ONE = sprite("repeat_one");
	public static final Identifier POWER_ON = sprite("power_on");
	public static final Identifier POWER_OFF = sprite("power_off");
	public static final Identifier VOLUME = sprite("volume");
	public static final Identifier VIEW_TREE = sprite("view_tree");
	public static final Identifier VIEW_LIST = sprite("view_list");
	public static final Identifier REFRESH = sprite("refresh");
	public static final Identifier PLUS = sprite("plus");
	public static final Identifier REMOVE = sprite("remove");
	public static final Identifier EXCLUDED = sprite("excluded");
	public static final Identifier EXCLUDE = sprite("exclude");
	public static final Identifier LED_ON = sprite("led_on");
	public static final Identifier LED_OFF = sprite("led_off");
	public static final Identifier FOLDER = sprite("folder");
	public static final Identifier PLAYLIST = sprite("playlist");
	public static final Identifier TRACK = sprite("track");
	public static final Identifier PC = sprite("pc");
	public static final Identifier USB = sprite("usb");
	public static final Identifier STREAM = sprite("stream");
	public static final Identifier LOCK = sprite("lock");

	/** Size of the square icons. */
	public static final int ICON = 9;
	/** The copper bar of the progress and the volume: rail height, knob size. */
	public static final int BAR_H = 5;
	public static final int KNOB_W = 5;
	public static final int KNOB_H = 9;

	public static final int COPPER = 0xFFD68448;
	public static final int COPPER_LIGHT = 0xFFF0AC70;
	public static final int COPPER_DARK = 0xFFA65C2E;
	/** Labels drawn on the window's grey, like vanilla container titles. */
	public static final int LABEL = 0xFF404040;
	public static final int TEXT = 0xFFFFFFFF;
	public static final int MUTED = 0xFFD0D0D0;
	public static final int CURRENT = 0xFFFFFF55;
	public static final int ABSENT = 0xFF505050;
	public static final int WARNING = 0xFFFFB050;

	/** Translation key prefix of the speaker screen. */
	public static final String KEY = "screen.ravecraft.speaker.";

	private SpeakerSprites() {
	}

	private static Identifier sprite(String name) {
		return RaveCraft.id("speaker/" + name);
	}

	/**
	 * The copper bar at {@code (x, y)}, {@code w} wide: the rail, the fill up to the knob when {@code filled}, and the
	 * knob at {@code fraction} (0 to 1) of the way, centred on the rail; a {@code knobAlpha} of 0 leaves it out.
	 */
	public static void copperBar(GuiGraphicsExtractor graphics, int x, int y, int w, float fraction, boolean filled,
			float knobAlpha) {
		graphics.blitSprite(RenderPipelines.GUI_TEXTURED, PROGRESS_TRACK, x, y, w, BAR_H);
		int knobX = x + Math.round((w - KNOB_W) * fraction);
		if (filled && knobX > x + 1) {
			graphics.blitSprite(RenderPipelines.GUI_TEXTURED, PROGRESS_FILL, x + 1, y + 1, knobX - x - 1 + KNOB_W / 2,
					BAR_H - 2);
		}
		if (knobAlpha > 0) {
			graphics.blitSprite(RenderPipelines.GUI_TEXTURED, PROGRESS_KNOB, knobX, y - (KNOB_H - BAR_H) / 2, KNOB_W,
					KNOB_H, knobAlpha);
		}
	}

	/** The 5 px arrow of a folder row in a tree: pointing right when folded, down when open. */
	public static void drawArrow(GuiGraphicsExtractor graphics, int x, int y, boolean expanded) {
		for (int i = 0; i < 3; i++) {
			if (expanded) {
				graphics.fill(x + i, y + 1 + i, x + 5 - i, y + 2 + i, 0xFF3A3A3A);
			} else {
				graphics.fill(x + 1 + i, y + i, x + 2 + i, y + 5 - i, 0xFF3A3A3A);
			}
		}
	}

	/**
	 * The hover of a small button inside a list row (add, remove): brighter than the row's own hover, with a light
	 * outline, so it stands out over a hovered row.
	 */
	public static void cellHover(GuiGraphicsExtractor graphics, int x, int y, int right, int bottom) {
		graphics.fill(x, y, right, bottom, 0x50FFFFFF);
		graphics.fill(x, y, right, y + 1, 0x90FFFFFF);
		graphics.fill(x, bottom - 1, right, bottom, 0x90FFFFFF);
		graphics.fill(x, y + 1, x + 1, bottom - 1, 0x90FFFFFF);
		graphics.fill(right - 1, y + 1, right, bottom - 1, 0x90FFFFFF);
	}

	/** {@code text} cut to {@code maxWidth} pixels, ending with an ellipsis when it had to be cut. */
	public static String fit(Font font, String text, int maxWidth) {
		if (font.width(text) <= maxWidth) {
			return text;
		}
		String ellipsis = CommonComponents.ELLIPSIS.getString();
		int room = maxWidth - font.width(ellipsis);
		return room <= 0 ? "" : font.plainSubstrByWidth(text, room) + ellipsis;
	}
}
